const trCache = new Map();
function tr(s) {
  if (!s) return s;
  const key = s; if (trCache.has(key)) return trCache.get(key);
  let out = trCore(s.trim());
  const lead = s.match(/^\s*/)[0], trail = s.match(/\s*$/)[0]; out = lead + out + trail;
  if (trCache.size < 5000) trCache.set(key, out);
  return out;
}
function trCore(t) {
  if (!t || !/[A-Za-zÄÖÜäöüß]/.test(t)) return t;
  if (EN[t] !== undefined) return EN[t];
  if (t.includes(' · ')) return t.split(' · ').map(trCore).join(' · ');
  for (const [re, r] of RULES) if (re.test(t)) return t.replace(re, r);
  if (t.includes(', ')) { const parts = t.split(', '); if (parts.every(p => EN[p] !== undefined)) return parts.map(p => EN[p]).join(', '); }
  return t;
}
const TR_ATTRS = ['placeholder', 'aria-label', 'title'];
function trNode(n) {
  if (!S || S.lang !== 'en') return;
  if (n.nodeType === 3) { const v = tr(n.data); if (v !== n.data) n.data = v; return; }
  if (n.nodeType !== 1 || n.tagName === 'SCRIPT' || n.tagName === 'STYLE' || n.closest('[translate="no"]')) return;
  for (const a of TR_ATTRS) { const v = n.getAttribute(a); if (v) { const w = tr(v); if (w !== v) n.setAttribute(a, w); } }
  if (n.tagName === 'svg' || n.tagName === 'INPUT' || n.tagName === 'TEXTAREA') return;
  n.childNodes.forEach(trNode);
}
new MutationObserver(ms => { if (!S || S.lang !== 'en') return; for (const m of ms) m.addedNodes.forEach(trNode); }).observe(document.body, { childList: true, subtree: true });
